import json, subprocess, base64
import numpy as np

def ft2(tool, args=None):
    args = args or {}
    cmd = ['ft2', 'call', tool, json.dumps(args)]
    r = subprocess.run(cmd, capture_output=True, text=True, cwd='/workspace')
    out = r.stdout.strip()
    try:
        j = json.loads(out)
    except Exception:
        print('RAW:', out[:2000], r.stderr[:2000])
        raise
    if j.get('isError'):
        print('ERR', tool, json.dumps(j)[:2000])
    txt = ''
    if j.get('content'):
        txt = j['content'][0].get('text','')
        if len(txt) < 400:
            return txt
        try:
            return json.loads(txt)
        except Exception:
            return txt
    return txt

def to_b64(x, encoding='int16'):
    if encoding == 'int16':
        x = np.clip(x, -1.0, 1.0)
        d = (x * 32767.0).astype('<i2').tobytes()
    else:
        d = np.clip(x,-1.0,1.0).astype('<f4').tobytes()
    return base64.b64encode(d).decode()

def load_sample(inst, sample, data, sr, encoding='int16', name='s'):
    """data: float array normalized -1..1. resample assumption: tool treats pcm at 44100? we pass as is"""
    return ft2('sample_create_from_pcm', {'instrument':inst,'sample':sample,'pcm':to_b64(data,encoding),'encoding':encoding,'name':name})
